SELECT end_year, customer_id, first_end_date, pct_standard FROM (SELECT YEAR(end_date) AS end_year, customer_id, MIN(end_date) AS first_end_date, ROUND((100 * SUM(CASE WHEN plan = 'standard' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_standard FROM subscriptions WHERE start_date BETWEEN '2024-01-08' AND '2024-11-02' GROUP BY YEAR(end_date), customer_id) AS t WHERE pct_standard > 38;
